		lfApCharged = { "+{{lfApCharged}}% tears while your active item is fully charged." },
		lfApHunger_name = "Hungry Void",
		lfApHunger = {
			"{{lfApHunger}}% chance when you pick up a coin, bomb, key or heart to gain +1% damage until the end of the floor (up to 20)."
		},
		lfApVoid_name = "Absorption",
		lfApVoid = { "Using an active item grants +{{lfApVoid}}% damage until you leave the room (up to 3 times)." },
		lfAzBurn_name = "Hellfire",
		lfAzBurn = { "{{lfAzBurn}}% chance for your hits to set enemies on fire." },
		lfAzScapegoat_name = "Scapegoat",
		lfAzScapegoat = {
			"Once per room, the first hit you take is ignored and the nearest enemy takes 5x your damage instead.",
			{ "-10% damage.", "RED" }
		},
		lfAzSulfur_name = "Sulfur Flash",
		lfAzSulfur = {
			"{{lfAzSulfur}}% chance when entering a room with enemies to empower your Brimstone for the room (Sulfur)."
		},
		lfAzWings_name = "Wingbeat",
		lfAzWings = { "{{lfAzWings}}% chance to dodge a hit." },
		lfBbFlies_name = "Swarm",
		lfBbFlies = { "{{lfBbFlies}}% chance on kill to spawn a blue fly." },
		lfBbSoulDmg_name = "Blue Blood",
