		lfBbStench_name = "Stench of Death",
		lfBbStench = { "When hit, release a poison cloud: enemies nearby take 3x your damage.", { "-5% tears.", "RED" } },
		lfBeCandle_name = "Candle of Faith",
		lfBeCandle = {
			"When a wisp dies, it bursts with holy light: enemies nearby take 3x your damage.",
			{ "-5% damage.", "RED" }
